/* Scene recall and original collocation transfer reuse the existing backup. */
let replayRun=null,replayAttempt=null,replayFilter='all',phraseRun=null,phraseAttempt=null;
let memorySpeechGeneration=0,memorySpeechTimer=null,memorySpeaking=false;
let PHRASE_INDEX=new Map();
function buildPhraseIndex(){PHRASE_INDEX=new Map((typeof WORDSCENE_PHRASES!=='undefined'?WORDSCENE_PHRASES:[]).map(row=>[row.id,row]));}
function memoryHeader(title,description){return `<div class="reader-top memory-top"><a class="back-link" href="#practice">← 听读练习</a><a class="text-link" href="#review">今日复习 →</a></div><section class="page-heading"><div class="serial-kicker">REMEMBER · RECONNECT · USE</div><h1>${esc(title)}</h1><p>${esc(description)}</p></section>`;}
function memoryGapHtml(text,label){return esc(text).replace('________',`<span class="memory-blank">〔${esc(label)}〕</span>`);}
function memoryEntries(){const n=replayCandidates().length;return `<section class="memory-entry-grid" aria-label="剧情记忆与搭配"><a class="memory-entry" href="#practice/replay"><small>RETURN TO THE SCENE</small><h2>错词剧情回放</h2><p>${n?`${n} 个词需要再见一面`:'从上次的章节试着回忆'} · 把词放回人物与线索里</p><span>开始回想 →</span></a><a class="memory-entry" href="#practice/phrases"><small>WORDS THAT WORK TOGETHER</small><h2>搭配拼接</h2><p>${WORDSCENE_PHRASE_META.length} 组小说表达 · 拼回原句，再换情境使用</p><span>把词连起来 →</span></a></section>`;}
const memoryHubBefore=novelStudyHub;
novelStudyHub=function(){memoryHubBefore();main.querySelector('.page-heading')?.insertAdjacentHTML('afterend',memoryEntries());};
const memoryReviewBefore=review;
review=function(){memoryReviewBefore();if(!skillQuiz)main.querySelector('.page-heading')?.insertAdjacentHTML('afterend',memoryEntries());};
const memoryLibraryBefore=library;
library=function(){memoryLibraryBefore();main.querySelector('.novel-feature-grid')?.insertAdjacentHTML('afterend',`<section class="memory-home-strip"><p>昨天没记住的词，今天换个方式再遇见。</p><a href="#practice/replay">错词剧情回放 →</a><a href="#practice/phrases">搭配拼接 →</a></section>`);};
const memoryLessonsBefore=novelLessonPanels;
novelLessonPanels=function(chapter){const related=WORDSCENE_PHRASE_META.filter(row=>row.chapters.includes(chapter.id));return memoryLessonsBefore(chapter)+(related.length?`<section class="novel-lesson"><small>本章表达 · 换情境使用</small><h2>把单词和它的搭配一起记。</h2><p>先拼回本章原句，再换到校园或工作情境检验。</p><div class="memory-link-list">${related.map(row=>`<a class="button secondary" href="#practice/phrases/${row.id}">${esc(clozeExpected(row.word))} · 搭配拼接 →</a>`).join('')}</div></section>`:'');};
const memoryProgressBefore=progress;
progress=function(){memoryProgressBefore();const recall=Object.entries(state.training).filter(([key])=>key.startsWith('replay:')),phrases=Object.entries(state.training).filter(([key])=>key.startsWith('phrase:'));main.querySelector('.progress-grid')?.insertAdjacentHTML('afterend',`<section class="progress-card"><h2>从剧情回忆，到搭配使用</h2><p>剧情回放 ${recall.length} 项记录 · 搭配迁移 ${phrases.length} 组记录。搭配只有新情境的独立作答才记成绩。</p>${phrases.sort((a,b)=>b[1].updatedAt-a[1].updatedAt).slice(0,5).map(([key,r])=>`<p><a class="text-link" href="#practice/phrases/${key.slice(7)}">${esc(key.slice(7).replace(/-/g,' '))} →</a> · ${r.correct?'最近迁移正确':'需要再练'}</p>`).join('')}<a class="text-link" href="#practice/replay">回到错词剧情 →</a></section>`);};
const memoryWordBefore=wordModal;
wordModal=function(id){if(main.dataset.view==='memory-replay'&&replayAttempt&&!replayAttempt.checked)replayAttempt.assisted=true;if(main.dataset.view==='memory-phrase'&&phraseAttempt?.phase==='transfer'&&!phraseAttempt.transfer.checked)phraseAttempt.transfer.assisted=true;memoryWordBefore(id);const related=WORDSCENE_PHRASE_META.filter(row=>row.word===id);if(related.length)wordDialog.querySelector('.word-source')?.insertAdjacentHTML('beforebegin',`<div class="memory-link-list">${related.map(row=>`<a class="text-link" href="#practice/phrases/${row.id}">用 ${esc(clozeExpected(id))} 练搭配 →</a>`).join('')}</div>`);};

function replayReference(id){const refs=SERIAL_WORD_CHAPTERS.get(id)||[];return refs.find(r=>r.id===state.serial.lastChapter)||refs.find(r=>state.serial.completed.includes(r.id))||refs[0];}
function replayRouteChapter(id){return replayRun?.items[replayRun.index]?.id===id?replayRun.items[replayRun.index].ref:replayReference(id);}
function replayCandidates(filter='all'){
 const rows=[];
 for(const id of new Set([...Object.keys(state.words),...Object.keys(state.skills)])){
  const ref=replayReference(id);if(!ref)continue;const skills=state.skills[id]||{},old=state.words[id];
  const weak=['listen','spell','read'].filter(kind=>skills[kind]?.stage===0),due=['listen','spell','read'].filter(kind=>skills[kind]?.due<=today()).sort((a,b)=>skills[a].due.localeCompare(skills[b].due));
  let kind,priority;
  if(filter!=='all'){if(weak.includes(filter)){kind=filter;priority=0;}else if(due.includes(filter)){kind=filter;priority=1;}else if(filter==='spell'&&old&&(old.stage===0||old.due<=today())){kind='spell';priority=old.stage===0?0:1;}}
  else if(weak.length){kind=weak[0];priority=0;}else if(old?.stage===0){kind='spell';priority=0;}else if(due.length){kind=due[0];priority=1;}else if(old?.due<=today()){kind='spell';priority=1;}
  if(kind){const recent=priority===0&&filter==='all'?Math.max(0,...weak.map(key=>skills[key].updatedAt||0),old?.stage===0?Date.parse(old.last||'')||0:0):skills[kind]?.updatedAt||Date.parse(old?.last||'')||0;rows.push({id,kind,ref,priority,due:skills[kind]?.due||old?.due||'',updatedAt:recent,reason:priority===0?SKILL_LABELS[kind]+'待重练':SKILL_LABELS[kind]+'已到期'});}
 }
 return rows.sort((a,b)=>a.priority-b.priority||(a.priority===0?b.updatedAt-a.updatedAt:a.due.localeCompare(b.due))||a.id.localeCompare(b.id));
}
function replayMenu(){const rows=replayCandidates(replayFilter),count=replayCandidates().length;main.dataset.view='memory-menu';main.innerHTML=memoryHeader('回到那一幕，再想起这个词。','先用剧情回忆，再核对原句。每轮最多八词，优先回放最近答错和已经到期的词。')+`<section class="novel-lesson"><h2>${count?`${count} 个词，等你回到故事里。`:'今天还没有需要回放的错词或到期词。'}</h2><div class="memory-filters" aria-label="复习分项">${[['all','全部'],['listen','听出'],['spell','拼对'],['read','看懂']].map(([key,label])=>`<button data-memory-filter="${key}" aria-pressed="${replayFilter===key}" class="${replayFilter===key?'selected':''}">${label}</button>`).join('')}</div><p>当前分项有 ${rows.length} 词；每个词回到自己的小说片段，听力薄弱词优先用英文段落回放。</p><div class="training-actions"><button class="button" data-memory-action="replay-start" ${rows.length?'':'disabled'}>回放 ${Math.min(8,rows.length)} 个词 →</button><button class="button secondary" data-memory-action="replay-fresh">从上次章节试练八词</button></div><p class="practice-label">刷新会结束未提交的一轮；已提交结果保留。没有小说语境的自添词可继续使用原词库复习。</p></section><section class="novel-lesson"><h2>这轮会回到哪些地方？</h2>${rows.length?rows.slice(0,8).map(row=>`<p>${esc(row.ref.bookTitle)} · 第 ${row.ref.number} 章 · ${esc(row.ref.title)} <span class="memory-tag">${row.reason}</span></p>`).join(''):'<p>读过一章、做过练习后，这里会依据你的记录安排回放。</p>'}</section>`;applyPreferences();}
function replayStart(fresh=false,retry=false){let items;if(retry&&replayRun)items=replayRun.items.filter((item,i)=>!replayRun.results[i]?.correct||replayRun.results[i]?.assisted);else if(fresh){const chapter=novelStudyChapter();items=shuffle(chapter.wordIds||serialTerms(chapter).map(t=>t.id)).slice(0,8).map(id=>({id,kind:'spell',ref:replayReference(id),reason:'本章试练'}));}else items=replayCandidates(replayFilter).slice(0,8);if(!items.length){toast('当前没有需要回放的词，可以从上次章节试练。');return;}replayRun={items,index:0,results:[]};replayAttempt=null;replayGoItem();}
function replayGoItem(){const item=replayRun.items[replayRun.index],hash='#practice/replay/'+item.id+'/'+item.kind;if(location.hash===hash)render();else location.hash=hash;scrollTrainingStart();}
function replayPage(id,kind='spell'){
 if(id==='done'){replayResult();return;}const ref=replayRouteChapter(id),chapter=ref&&SERIAL_CHAPTER_INDEX.get(ref.id);if(!ref||!chapter?.cn?.length){main.innerHTML=memoryHeader('这条线索暂时找不到。','请从错词回放总览重新选择。')+'<a class="button" href="#practice/replay">回到回放总览 →</a>';return;}
 if(!['listen','spell','read'].includes(kind))kind='spell';
 if(!replayRun||replayRun.items[replayRun.index]?.id!==id){replayRun={items:[{id,kind,ref,reason:'单词回放'}],index:0,results:[]};replayAttempt=null;}
 replayRun.items[replayRun.index].kind=kind;
 if(!replayAttempt||replayAttempt.id!==id||replayAttempt.kind!==kind){const assisted=replayAttempt?.id===id&&(replayAttempt.assisted||replayAttempt.checked);const term=serialGameSlots(chapter).find(t=>t.id===id),example=novelWordExample(chapter,id);if(!term||!example){serialNotFound();return;}const marker=wordsceneMatches(example.marked,/\[\[([^|\]]+)\|([^\]]+)\]\]/g).find(m=>m[1]===id);replayAttempt={id,kind,chapter:chapter.id,term,example,surface:marker[2],answer:'',checked:false,assisted:Boolean(assisted),heard:false,options:kind==='read'?skillMeaningOptions({...getWord(id),id,meaning:term.meaning}):[]};}
 const s=replayAttempt;main.dataset.view='memory-replay';const prompt=s.kind==='read'?'这段英文里，加粗的词是什么意思？':s.kind==='listen'?'听完这段英文，写回线索词的实际词形。':'凭这幅剧情画面，写回英文原形。';
 const english=esc(s.example.marked).replace(/\[\[([^|\]]+)\|([^\]]+)\]\]/g,(_,key,surface)=>key===id?'<strong>'+surface+'</strong>':surface);
 main.innerHTML=memoryHeader('把那条线索，再找回来。','本轮直接使用原小说片段，提交后核对中文和对应英文。')+`<section class="memory-paper"><div class="quiz-top"><span>${replayRun.index+1} / ${replayRun.items.length} · ${SKILL_LABELS[kind]}</span><span>${esc(chapter.book.title)} · 第 ${chapter.number} 章</span></div><h2>${esc(chapter.title)}</h2><p class="practice-label">${NOVEL_STUDY_LABEL}</p><h3>${prompt}</h3>${kind==='read'?`<p class="novel-example" lang="en">${english}</p>`:`<div class="memory-scene">${serialMaskedScene(chapter,s.term)}</div>`}${kind==='listen'?`<div class="memory-audio"><button class="button secondary" data-memory-action="replay-audio">▷ 回放这一段英文</button><button class="text-link" data-memory-action="audio-stop">停止</button><p id="memory-audio-status" role="status">${s.heard?'本段已完整播放。':'先听完整段落；实际拼写可能是过去式或复数。'}</p><a class="text-link" href="#practice/replay/${id}/spell">改用剧情拼写 →</a></div>`:''}${kind==='read'?`<div class="novel-options">${s.options.map(w=>`<button data-memory-choice="${esc(w.id)}" aria-pressed="${s.answer===w.id}" class="${s.answer===w.id?'selected':''}" ${s.checked?'disabled':''}>${esc(w.meaning)}</button>`).join('')}</div>`:`<form id="memory-replay-form"><label for="memory-replay-input">${kind==='listen'?'英文实际词形':'英文原形'}</label><input class="spelling-input" id="memory-replay-input" maxlength="80" value="${esc(s.answer)}" autocomplete="off" autocapitalize="off" autocorrect="off" spellcheck="false" ${s.checked?'disabled':''}><button class="button" type="submit" ${s.checked?'disabled':''}>核对这条线索 →</button></form>`}${!s.checked?`<div class="training-actions">${kind==='read'?'<button class="button" data-memory-action="replay-submit">核对词义 →</button>':''}<button class="text-link" data-memory-action="replay-reveal">暂时想不起，展开原句</button></div><p class="practice-label">展开原句或查看词卡后，这一项只作核对，不增加掌握记录。</p>`:replayFeedback(chapter,s)}<div class="memory-source-link"><a class="text-link" data-memory-source href="${novelStudyUrl(chapter,'read')}">回到这章小说 →</a></div></section>`;applyPreferences();
}
function replayCorrect(s){return s.kind==='read'?s.answer===s.id:isClozeCorrect(s.answer,s.kind==='listen'?s.surface:s.id);}
function replayFeedback(chapter,s){return `<section class="memory-feedback" role="status"><h3>${s.assisted?'原句已展开，这一项只作核对。':replayCorrect(s)?'线索找回来了。':'这幅画面，值得再看一眼。'}</h3><p><strong lang="en">${esc(clozeExpected(s.id))}</strong> · ${esc(s.term.meaning)}${s.surface.toLowerCase()!==clozeExpected(s.id).toLowerCase()?' · 原句词形 '+esc(s.surface):''}</p><p>${esc(listeningPlain(chapter.cn[s.term.paragraph]))}</p><p class="novel-example" lang="en">${esc(s.example.text)}</p><p class="practice-label">依据：第 ${s.term.paragraph+1} 段。${s.assisted?'本项不记成绩。':'结果已进入对应复习分项。'}</p><button class="button" data-memory-action="replay-next">${replayRun.index+1===replayRun.items.length?'看看这轮回忆 →':'回到下一幕 →'}</button></section>`;}
function replaySubmit(reveal=false){const s=replayAttempt;if(!s||s.checked)return;if(reveal){s.assisted=true;s.answer=s.kind==='read'?s.id:s.kind==='listen'?s.surface:clozeExpected(s.id);}else{if(!s.answer.trim()){toast('先写下或选择你回忆到的答案。');return;}if(s.kind==='listen'&&!s.heard&&!s.assisted){toast('先听完整段落，再核对；朗读不可用时可改用剧情拼写。');return;}}memoryStopAudio();s.checked=true;const correct=replayCorrect(s);replayRun.results[replayRun.index]={correct,assisted:s.assisted};if(!s.assisted){storeTraining('replay:'+s.id+':'+s.kind,correct?1:0,1);recordInSkills(s.id,correct,s.kind==='listen'?['listen','spell']:[s.kind]);}replayPage(s.id,s.kind);main.querySelector('.memory-feedback').scrollIntoView({block:'start'});}
function replayResult(){main.dataset.view='memory-menu';if(!replayRun){replayMenu();return;}const results=replayRun.results,correct=results.filter(r=>r.correct&&!r.assisted).length,assisted=results.filter(r=>r.assisted).length;main.innerHTML=memoryHeader('这些词，又回到你的故事里了。','每一次回忆，都对应实际的小说片段。')+`<section class="novel-lesson"><div class="result-number">${correct}<small> / ${results.length} 项独立回忆正确</small></div><p>${assisted} 项借助原句核对；这些项不增加掌握记录。答错的词已安排重练。</p><div class="training-actions"><button class="button" data-memory-action="replay-retry" ${correct===results.length?'disabled':''}>再回想未记住的词</button><a class="button secondary" href="#practice/phrases">试试搭配拼接 →</a><a class="text-link" href="#practice/replay">回到回放总览</a></div></section>`;applyPreferences();}

function phrasePriority(row){const score=state.training['phrase:'+row.id];return !score?1:score.correct<score.total?0:state.words[row.word]?.due<=today()?1:2;}
function phraseMenu(){buildPhraseIndex();main.dataset.view='memory-menu';const rows=[...PHRASE_INDEX.values()].sort((a,b)=>phrasePriority(a)-phrasePriority(b)||a.id.localeCompare(b.id));main.innerHTML=memoryHeader('让单词，带上它的搭配。','先拼回小说里的表达，再换到校园或工作情境。点击词块即可拼接，不需要拖动。')+`<section class="novel-lesson"><h2>${rows.length} 组真实小说表达</h2><p>每轮六组，优先练迁移答错或尚未练过的搭配。小说拼接是学习环节；新情境的独立作答才记成绩。</p><button class="button" data-memory-action="phrase-start">拼接六组搭配 →</button><p class="practice-label">${NOVEL_STUDY_LABEL} 刷新会结束未提交的一轮。</p></section><section class="memory-phrase-list">${rows.map(row=>{const result=state.training['phrase:'+row.id],c=SERIAL_CHAPTER_INDEX.get(row.refs[0].chapter);return `<a href="#practice/phrases/${row.id}"><span><strong lang="en">${esc(clozeExpected(row.word))} ${row.prep}</strong><small>${esc(row.meaning)} · ${esc(c.book.title)}第 ${c.number} 章</small></span><span class="memory-tag">${result?result.correct?'迁移正确':'需要再练':'尚未练习'} →</span></a>`;}).join('')}</section>`;applyPreferences();}
function phraseStart(retry=false){const rows=retry&&phraseRun?phraseRun.ids.filter((id,i)=>!phraseRun.results[i]?.correct||phraseRun.results[i]?.assisted):[...PHRASE_INDEX.values()].sort((a,b)=>phrasePriority(a)-phrasePriority(b)||a.id.localeCompare(b.id)).slice(0,6).map(r=>r.id);if(!rows.length){toast('这一轮已全部完成。');return;}phraseRun={ids:rows,index:0,results:[]};phraseAttempt=null;phraseGoItem();}
function phraseGoItem(){const hash='#practice/phrases/'+phraseRun.ids[phraseRun.index];if(location.hash===hash)render();else location.hash=hash;scrollTrainingStart();}
function phraseRouteChapter(id){return PHRASE_INDEX.get(id)?.refs[0]?.chapter;}
function phrasePage(id){buildPhraseIndex();if(id==='done'){phraseResult();return;}const row=PHRASE_INDEX.get(id),ref=row?.refs[0],chapter=ref&&SERIAL_CHAPTER_INDEX.get(ref.chapter);if(!row||!chapter?.cn?.[ref.paragraph]?.length||!chapter.en[ref.paragraph].includes(ref.marked)){main.innerHTML=memoryHeader('这组搭配暂时找不到。','请从搭配总览重新选择。')+'<a class="button" href="#practice/phrases">回到搭配总览 →</a>';return;}
 if(!phraseRun||phraseRun.ids[phraseRun.index]!==id){phraseRun={ids:[id],index:0,results:[]};phraseAttempt=null;}
 if(!phraseAttempt||phraseAttempt.id!==id)phraseAttempt={id,phase:'story',tokens:[],storyChecked:false,storyRevealed:false,transfer:{answer:'',checked:false,assisted:false},bank:shuffle([ref.surface,row.prep,...row.transfer.distractors]),options:shuffle([row.prep,...row.transfer.distractors])};
 const s=phraseAttempt,example=novelWordExample(chapter,row.word),masked=example.marked.replace(ref.marked,'________'),transfer=row.transfer.prefix+'________'+row.transfer.suffix;main.dataset.view='memory-phrase';
 main.innerHTML=memoryHeader('把词连起来，换个情境用。','同一个搭配，先放回小说，再用到一个新的真实生活情境。')+`<section class="memory-paper"><div class="quiz-top"><span>搭配 ${phraseRun.index+1} / ${phraseRun.ids.length}</span><span>${s.phase==='story'?'01 · 小说拼接':'02 · 新情境迁移'}</span></div><p class="practice-label">${NOVEL_STUDY_LABEL}</p>${s.phase==='story'?`<div class="serial-kicker">${esc(chapter.book.title)} · 第 ${chapter.number} 章</div><h2>把「${esc(row.meaning)}」的表达拼回来。</h2><p class="memory-scene">${serialMaskedScene(chapter,{id:row.word,paragraph:ref.paragraph})}</p><p class="novel-example" lang="en">${memoryGapHtml(listeningPlain(masked),'搭配')}</p><div class="memory-built" aria-label="已拼接的词块" aria-live="polite">${[0,1].map(i=>`<span>${s.tokens[i]?esc(s.tokens[i]):'第 '+(i+1)+' 块'}</span>`).join('')}</div><div class="memory-token-bank" aria-label="可选择的词块">${s.bank.map(token=>`<button data-memory-token="${esc(token)}" ${s.storyChecked||s.tokens.includes(token)?'disabled':''} lang="en">${esc(token)}</button>`).join('')}</div>${!s.storyChecked?'<div class="training-actions"><button class="button" data-memory-action="phrase-check">核对小说表达 →</button><button class="text-link" data-memory-action="phrase-undo">退回一块</button><button class="text-link" data-memory-action="phrase-reveal">展开表达，先学一遍</button></div>':`<section class="memory-feedback" role="status"><h3>${s.storyRevealed?'先记住这个表达。':phraseStoryCorrect(row,s)?'词块连起来了。':'沿着原句，换个连接方式。'}</h3><p><strong lang="en">${esc(ref.surface)} ${row.prep}</strong> · ${esc(row.meaning)}</p><p>${esc(row.note)}</p><p class="novel-example" lang="en">${esc(example.text)}</p><p class="practice-label">依据：本章第 ${ref.paragraph+1} 段。小说拼接只作学习，不增加词汇掌握。</p><button class="button" data-memory-action="phrase-transfer">换一个情境检验 →</button></section>`}`:`<h2>这次，换到小说以外。</h2><p>选择让句子成立的连接词；先作答，再看搭配和解释。</p><p class="novel-example" lang="en">${memoryGapHtml(transfer,'连接词')}</p><div class="novel-options">${s.options.map(option=>`<button data-memory-prep="${option}" aria-pressed="${s.transfer.answer===option}" class="${s.transfer.answer===option?'selected':''}" ${s.transfer.checked?'disabled':''} lang="en">${option}</button>`).join('')}</div>${!s.transfer.checked?'<div class="training-actions"><button class="button" data-memory-action="phrase-submit">核对新情境 →</button><button class="text-link" data-memory-action="phrase-transfer-reveal">查看表达与解释</button></div>':`<section class="memory-feedback" role="status"><h3>${s.transfer.assisted?'这项只作参考核对。':s.transfer.answer===row.prep?'换了情境，也用对了。':'这组搭配，下一轮再见。'}</h3><p class="novel-example" lang="en">${esc(row.transfer.prefix+row.prep+row.transfer.suffix)}</p><p><strong lang="en">${esc(clozeExpected(row.word))} ${row.prep}</strong> · ${esc(row.meaning)}</p><p>${esc(row.note)}</p><p class="practice-label">${s.transfer.assisted?'参考核对不增加词汇掌握。':'迁移结果已保存；本词的“看懂”分项已更新。'}</p><button class="button" data-memory-action="phrase-next">${phraseRun.index+1===phraseRun.ids.length?'看看这轮搭配 →':'拼下一组表达 →'}</button></section>`}` }<div class="memory-source-link"><a class="text-link" data-memory-source href="${novelStudyUrl(chapter,'read')}">回到原小说 →</a> <a class="text-link" href="#practice/phrases">搭配总览 →</a></div></section>`;applyPreferences();
}
function phraseStoryCorrect(row,s){return s.tokens.length===2&&s.tokens[0].toLowerCase()===row.refs[0].surface.toLowerCase()&&s.tokens[1]===row.prep;}
function phraseSubmit(reveal=false){const s=phraseAttempt,row=PHRASE_INDEX.get(s?.id);if(!row||s.phase!=='transfer'||s.transfer.checked)return;if(reveal){s.transfer.assisted=true;s.transfer.answer=row.prep;}else if(!s.transfer.answer){toast('先选择连接词，再核对新情境。');return;}s.transfer.checked=true;const correct=s.transfer.answer===row.prep;phraseRun.results[phraseRun.index]={correct,assisted:s.transfer.assisted};if(!s.transfer.assisted){storeTraining('phrase:'+row.id,correct?1:0,1);recordInSkills(row.word,correct,['read']);}phrasePage(s.id);main.querySelector('.memory-feedback').scrollIntoView({block:'start'});}
function phraseResult(){main.dataset.view='memory-menu';if(!phraseRun){phraseMenu();return;}const r=phraseRun.results,correct=r.filter(x=>x.correct&&!x.assisted).length;main.innerHTML=memoryHeader('搭配连起来，表达也更完整了。','小说学习与新情境检验分开记录，帮助你看到是否真的能换个地方使用。')+`<section class="novel-lesson"><div class="result-number">${correct}<small> / ${r.length} 项独立迁移正确</small></div><p>${r.filter(x=>x.assisted).length} 项参考核对不计成绩。下轮优先练尚未迁移正确的表达。</p><div class="training-actions"><button class="button" data-memory-action="phrase-retry" ${correct===r.length?'disabled':''}>重练未掌握的搭配</button><a class="button secondary" href="#practice/replay">回放我的错词 →</a><a class="text-link" href="#practice/phrases">回到搭配总览</a></div></section>`;applyPreferences();}

function memoryStopAudio(message){memorySpeechGeneration++;clearTimeout(memorySpeechTimer);if(memorySpeaking&&'speechSynthesis'in window)speechSynthesis.cancel();memorySpeaking=false;if(message){const status=document.getElementById('memory-audio-status');if(status)status.textContent=message;}}
function replayPlay(){const s=replayAttempt;if(!s||s.kind!=='listen')return;memoryStopAudio();serialStopAudio();listeningStop();if(!('speechSynthesis'in window)||typeof SpeechSynthesisUtterance==='undefined'){memoryStopAudio('当前浏览器不支持朗读，可以改用剧情拼写。');return;}const voices=speechSynthesis.getVoices(),voice=voices.find(v=>/^en[-_]/i.test(v.lang));if(voices.length&&!voice){memoryStopAudio('设备没有可用英语语音，可以改用剧情拼写。');return;}const chapter=SERIAL_CHAPTER_INDEX.get(s.chapter),chunks=listeningChunks(listeningPlain(chapter.en[s.term.paragraph])),generation=memorySpeechGeneration,hash=location.hash;memorySpeaking=true;
 const next=index=>{if(generation!==memorySpeechGeneration||replayAttempt!==s||location.hash!==hash)return;clearTimeout(memorySpeechTimer);if(index===chunks.length){s.heard=true;memorySpeaking=false;document.getElementById('memory-audio-status').textContent='本段已完整播放，可以填写实际词形。';return;}const utterance=new SpeechSynthesisUtterance(chunks[index]);utterance.lang=voice?.lang||'en-GB';if(voice)utterance.voice=voice;utterance.rate=state.preferences.rate||.85;document.getElementById('memory-audio-status').textContent=`正在回放第 ${index+1} / ${chunks.length} 个片段…`;memorySpeechTimer=setTimeout(()=>memoryStopAudio('语音没有完成，请重试或改用剧情拼写。'),30000);utterance.onend=()=>next(index+1);utterance.onerror=()=>{if(generation===memorySpeechGeneration)memoryStopAudio('英语朗读未能完成，请重试或改用剧情拼写。');};try{speechSynthesis.speak(utterance);}catch(_){memoryStopAudio('英语语音暂时不可用，可以改用剧情拼写。');}};next(0);
}
const memoryRenderBefore=render;
render=function(){const [route,section,id,kind]=location.hash.slice(1).split('/');if(route==='practice'&&['replay','phrases'].includes(section)){wordDialog.close();utilityDialog.close();document.body.classList.remove('focus-mode');clearInterval(trainingClock);if(section==='replay')id?replayPage(id,kind):replayMenu();else id?phrasePage(id):phraseMenu();updateNav();}else memoryRenderBefore();};
document.addEventListener('click',event=>{
 const source=event.target.closest('[data-memory-source]');if(source){if(main.dataset.view==='memory-replay'&&replayAttempt&&!replayAttempt.checked)replayAttempt.assisted=true;if(main.dataset.view==='memory-phrase'&&phraseAttempt?.phase==='transfer'&&!phraseAttempt.transfer.checked)phraseAttempt.transfer.assisted=true;return;}
 const b=event.target.closest('[data-memory-action],[data-memory-filter],[data-memory-choice],[data-memory-token],[data-memory-prep]');if(!b)return;event.preventDefault();event.stopImmediatePropagation();
 if(b.dataset.memoryFilter){replayFilter=b.dataset.memoryFilter;replayMenu();return;}
 if(b.dataset.memoryChoice){if(replayAttempt&&!replayAttempt.checked){replayAttempt.answer=b.dataset.memoryChoice;replayPage(replayAttempt.id,replayAttempt.kind);}return;}
 if(b.dataset.memoryToken){if(phraseAttempt?.phase==='story'&&!phraseAttempt.storyChecked&&phraseAttempt.tokens.length<2){phraseAttempt.tokens.push(b.dataset.memoryToken);phrasePage(phraseAttempt.id);}return;}
 if(b.dataset.memoryPrep){if(phraseAttempt?.phase==='transfer'&&!phraseAttempt.transfer.checked){phraseAttempt.transfer.answer=b.dataset.memoryPrep;phrasePage(phraseAttempt.id);}return;}
 const action=b.dataset.memoryAction;
 if(action==='replay-start')replayStart();else if(action==='replay-fresh')replayStart(true);else if(action==='replay-retry')replayStart(false,true);else if(action==='replay-submit')replaySubmit();else if(action==='replay-reveal')replaySubmit(true);else if(action==='replay-audio')replayPlay();else if(action==='audio-stop')memoryStopAudio('播放已停止。');
 else if(action==='replay-next'&&replayAttempt?.checked){replayRun.index++;replayAttempt=null;if(replayRun.index<replayRun.items.length)replayGoItem();else location.hash='#practice/replay/done';}
 else if(action==='phrase-start')phraseStart();else if(action==='phrase-retry')phraseStart(true);
 else if(action==='phrase-undo'&&phraseAttempt&&!phraseAttempt.storyChecked){phraseAttempt.tokens.pop();phrasePage(phraseAttempt.id);}
 else if(['phrase-check','phrase-reveal'].includes(action)&&phraseAttempt?.phase==='story'&&!phraseAttempt.storyChecked){if(action==='phrase-check'&&phraseAttempt.tokens.length!==2){toast('先点选两个词块，再核对。');return;}const row=PHRASE_INDEX.get(phraseAttempt.id);if(action==='phrase-reveal'){phraseAttempt.storyRevealed=true;phraseAttempt.tokens=[row.refs[0].surface,row.prep];}phraseAttempt.storyChecked=true;phrasePage(row.id);main.querySelector('.memory-feedback').scrollIntoView({block:'start'});}
 else if(action==='phrase-transfer'&&phraseAttempt?.storyChecked){phraseAttempt.phase='transfer';phrasePage(phraseAttempt.id);scrollTrainingStart();}
 else if(action==='phrase-submit')phraseSubmit();else if(action==='phrase-transfer-reveal')phraseSubmit(true);
 else if(action==='phrase-next'&&phraseAttempt?.transfer.checked){phraseRun.index++;phraseAttempt=null;if(phraseRun.index<phraseRun.ids.length)phraseGoItem();else location.hash='#practice/phrases/done';}
},true);
document.addEventListener('input',event=>{if(event.target.id==='memory-replay-input'&&replayAttempt&&!replayAttempt.checked)replayAttempt.answer=event.target.value;});
document.addEventListener('submit',event=>{if(event.target.id!=='memory-replay-form')return;event.preventDefault();event.stopImmediatePropagation();replaySubmit();},true);
window.addEventListener('hashchange',()=>memoryStopAudio());window.addEventListener('pagehide',()=>memoryStopAudio());
document.addEventListener('visibilitychange',()=>{if(document.hidden)memoryStopAudio('已停止后台播放，回到页面后可重新听。');});
